static addItem({ item, namespace = DEFAULT_NAMESPACE, layout, config, options = {}, }) {
    const salt = config.salt;
    const newItemData = getNewItemData({ item, config, salt, counter: config.counter, options });
    let counter = newItemData.counter;
    const newIdData = getNewId({ config, salt, counter, excludeIds: newItemData.excludeIds });
    counter = newIdData.counter;
    const newItem = Object.assign(Object.assign({}, item), { id: newIdData.id, data: newItemData.data, namespace });
    const saveDefaultLayout = pick(layout, ['h', 'w', 'x', 'y', 'parent']);
    const updateActions = Object.assign({ counter: { $set: counter } }, (options.useGlobalItems
        ? { globalItems: config.globalItems ? { $push: [newItem] } : { $set: [newItem] } }
        : { items: { $push: [newItem] } }));
    if (options.updateLayout) {
        const byId = options.updateLayout.reduce((memo, t) => {
            memo[t.i] = t;
            return memo;
        }, {});
        let newLayout;
        const newLayoutItem = Object.assign(Object.assign({}, saveDefaultLayout), { i: newItem.id });
        if (options.reflowLayoutOptions) {
            newLayout = reflowLayout({
                newLayoutItem,
                layout: config.layout.map((t) => (Object.assign(Object.assign({}, t), (byId[t.i] || {})))),
                reflowLayoutOptions: options.reflowLayoutOptions,
            });
        }
        else {
            newLayout = [
                ...config.layout.map((t) => (Object.assign(Object.assign({}, t), (byId[t.i] || {})))),
                Object.assign(Object.assign({}, saveDefaultLayout), { i: newItem.id }),
            ];
        }
        return update(config, Object.assign(Object.assign({}, updateActions), { layout: { $set: newLayout } }));
    }
