        items: [
            item('h1', 'title', {text: 'Обзор продаж', size: 'l'}, 0),
            item('m1', 'metric', {
                title: 'Выручка',
                value: '8,2 млн ₽',
                delta: '+12,4%',
                trend: 'up',
            }),
            item('m2', 'metric', {
                title: 'Активные пользователи',
                value: '24 531',
                delta: '+5,1%',
                trend: 'up',
            }),
            item('m3', 'metric', {
                title: 'Конверсия в заказ',
                value: '3,42%',
                delta: '−0,3%',
                trend: 'down',
            }),
            item('m4', 'metric', {
                title: 'Средний чек',
                value: '5 460 ₽',
                delta: '+1,8%',
                trend: 'up',
            }),
            item('c1', 'chart-line'),
            item('c2', 'chart-pie'),
            item('c3', 'chart-bar'),
            item('t1', 'text', {
                text: 'Заметки аналитика: онлайн-канал продолжает расти быстрее остальных. Розница стабильна, партнёрский канал просел после изменения условий программы. Рекомендуем пересмотреть структуру комиссий до конца квартала.',
            }),
        ],
        layout: [
            {i: 'h1', x: 0, y: 0, w: 36, h: 2},
            {i: 'm1', x: 0, y: 2, w: 9, h: 6},
            {i: 'm2', x: 9, y: 2, w: 9, h: 6},
            {i: 'm3', x: 18, y: 2, w: 9, h: 6},
            {i: 'm4', x: 27, y: 2, w: 9, h: 6},
            {i: 'c1', x: 0, y: 8, w: 24, h: 14},
